"""Supply complaint guidance and examples while preserving native tool choice."""

from pydantic import JsonValue

from experimental.curator.harness.preparation import PreparationRequest
from experimental.curator.harness.resources import (
    CapabilityContribution,
    CapabilityRegistrar,
    CapabilitySelection,
    RegistrationReceipt,
    SelectionRequest,
    SkillContribution,
    SkillSelection,
)
from experimental.curator.harness.state import Task
from experimental.curator.harness.strategies import CapabilityStrategy


DATA_GUIDANCE = """处理售后投诉时，以本次给出的时间、客户消息和本次适用的四份材料为依据：售后工作规则、订单记录、本月 CRM 投诉记录、问题分类表。不同店铺的规定可能不同，不沿用其他投诉的规则、事实或输出模板。
先确认当次材料：使用用户提供的内容、附件或工作目录中的原文件；路径不明时先查找。读清当次工作规则与问题分类表，查阅本次相关订单和 CRM 记录；需要统计或核对的范围由当次规则决定。读取结果被截断或分页未完时补读所需部分。当前上下文中已完整读取且仍适用于本次的材料直接复用，不重复读取或要求用户重发。"""

FINAL_GUIDANCE = """按当次规则处理，金额、时限、条件均取自材料；客户陈述、已核对事实和待核实情况分开。写办理状态时，先从现有输入记录或实际执行结果确定该订单该事项的每个动作到了哪一步，选定有依据的状态短语，再在客户回复和内部处理的对应句中沿用，不因改成安抚话术而升级状态。权限结论只说明能否直接办理，不证明已经办理。
对照写法：只有需审批的结论、没有提交成功证据时，客户和内部都用“需提交主管审批”；错误是内部写“需提交”，客户却写“已记录并提交”。在答复中记录诉求与对外提交是两个动作，不能用前者证明后者，也不能当作 CRM 已登记。若有对应事项提交成功的记录，两处都可写“已提交主管审批”，但不能据此写已批准或已赔付；发券、退换、CRM 登记和通知也只写各自动作有证据支持的进度。有完成证据就保留完成状态，不一律改待办；状态不明则说明待核实，不猜已完成。只把办理结论放入原规定段，不另列检查表；应执行的动作仍按当次要求办理，不以改措辞冒充执行。
最终答复先按当次规定的标题、段数和顺序组织内容，再把各项判断填入对应段。规则禁止增加其他段时，第一行就是当次第一个“## 段名”（段名取自当次规则），全部正文留在规定段内。反例是先写“材料已读完，分析如下”或计算摘要，再列规定标题；正例是直接从首个规定标题开始，把必要依据写在对应段中。无标题的一句导语也算段外正文，不加前后言，不删除必要业务分析。直接交付处理结果，不用计划或进度说明替代。
缺失、矛盾或读取失败只影响依赖它的结论：在规定段内交付已有依据的部分并说明具体缺口，必要时仅询问影响处理的缺失信息；不要猜测缺失规则，也不要因局部不确定放弃其余可完成的内容。"""

SKILL_NAME = "complaint-compensation"
SKILL_SOURCE = "curator-capability"
SKILL_ASSET = "complaint_compensation/SKILL.md"
COUNTING_NAME = "complaint-counting"
SKILL_SPECS = (
    (SKILL_NAME, SKILL_ASSET, "R1 compensation handling examples"),
    (COUNTING_NAME, "complaint_counting/SKILL.md", "R2 complaint counting examples"),
)
COMPENSATION_METHOD = (
    "分别回应两项，用总额度扣除历史补偿和本次应计入的券所得余量判断独立索赔，"
    "不因同额视为已经替代；结论放回当次规定的段落。"
)
COUNTING_GUIDANCE = (
    "统计同款同问题时，先对照《同款同问题计数》：先按当次规则确定同款范围，"
    "再用当月记录归类、按订单去重并核对本次是否已计入；"
    "起数、标记名称和通知部门沿用同一依据。"
)
COUNTING_FALLBACK = (
    "统计同款同问题时，按当次规则的同款口径纳入颜色范围，不只匹配完整带颜色编号，"
    "也不凭共有前缀合并不同型号；已有分类优先，空分类按本次分类表从描述归类；"
    "依给定时间筛选规则指定年月，按订单去重，本次同问题已计入则不重复增加，"
    "再按同一起数和当次阈值安排指定标记与通知部门。"
)
MISSING_BODY = (
    "案例正文未供给，按本次材料直接判断；不要声称已读案例，"
    "无需为找案例重复读取业务资料。"
)


class ComplaintCapability(CapabilityStrategy):
    """Prepare two example skills and delegate resource admission to the host."""

    def __init__(self, registrar: CapabilityRegistrar) -> None:
        self._registrar = registrar

    def register(self, contribution: CapabilityContribution) -> RegistrationReceipt:
        return self._registrar.register(contribution)

    def _prepare_skills(self, request: PreparationRequest) -> tuple[SkillContribution, ...]:
        contributions: list[SkillContribution] = []
        for name, asset, source in SKILL_SPECS:
            content = request.assets[asset]
            if not content.strip():
                raise ValueError(f"empty complaint example asset: {asset}")
            contributions.append(
                SkillContribution(
                    name=name,
                    owner="capability",
                    package=None,
                    files={"SKILL.md": content},
                    source=source,
                )
            )
        return tuple(contributions)

    async def select(self, request: SelectionRequest) -> CapabilitySelection:
        counts: dict[tuple[str, str], int] = {}
        for skill in request.skills:
            key = (skill.source, skill.name)
            counts[key] = counts.get(key, 0) + 1
        ambiguous = any(count > 1 for count in counts.values())
        targets = {(SKILL_SOURCE, name) for name, _, _ in SKILL_SPECS}
        available = {
            (skill.source, skill.name) for skill in request.skills if skill.available
        }
        bodies = set() if ambiguous else targets & available

        guidance = [DATA_GUIDANCE]
        if (SKILL_SOURCE, SKILL_NAME) in bodies:
            guidance.append(
                "规则补券与客户索赔并存时，先对照《规则补券与独立索赔》的同类案例："
                + COMPENSATION_METHOD
            )
        else:
            guidance.append(
                "规则补券与客户索赔并存时，" + COMPENSATION_METHOD
                + "本次补偿" + MISSING_BODY
            )
        if (SKILL_SOURCE, COUNTING_NAME) in bodies:
            guidance.append(COUNTING_GUIDANCE)
        else:
            guidance.append(COUNTING_FALLBACK + "本次计数" + MISSING_BODY)
        if ambiguous:
            guidance.append("本次 Skill 身份有重复，委托原生 Skill 选择，不宣称上述案例正文已供给。")
        guidance.append(FINAL_GUIDANCE)

        selected: tuple[SkillSelection, ...] | None = None
        if bodies:
            selected = tuple(
                SkillSelection(
                    name=skill.name,
                    source=skill.source,
                    delivery="body" if (skill.source, skill.name) in bodies else "catalog",
                )
                for skill in request.skills if skill.available
            )
        return CapabilitySelection(tools=None, skills=selected, guidance="\n".join(guidance))


def create(
    state: dict[str, JsonValue],
    task: Task,
    *,
    registrar: CapabilityRegistrar,
) -> ComplaintCapability:
    """Bind the supplied registrar; leave task identity and checkpoint untouched."""
    return ComplaintCapability(registrar)
